fresh = subprocess.run(["node", "gen.js", "1123"], capture_output=True, text=True).stdout; check("grove-1123.json is what core.js gives for seed 1123 now", fresh == open("grove-1123.json").read())
html = open("dryads.html").read(); check("dryads.html carries core.js whole, and fetches nothing", open("core.js").read() in html and not re.search(r"src=|<link|fetch\(|XMLHttpRequest|import ", html))
