    pr = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration:stream=codec_name,width,height,r_frame_rate", "-of", "json", "dryads.mp4"], capture_output=True, text=True).stdout; j = json.loads(pr)
    v = [s for s in j["streams"] if s["codec_name"] == "h264"]; au = [s for s in j["streams"] if s["codec_name"] in ("aac", "mp3")]
    check("the film: 1280 by 720 at 24 frames a second, with sound, as long as the piece", len(v) == 1 and len(au) == 1 and (v[0]["width"], v[0]["height"], v[0]["r_frame_rate"]) == (1280, 720, "24/1") and abs(float(j["format"]["duration"]) - g["duration"]) < 1.5, j["format"]["duration"])
