named = [f for f in re.findall(r"`([\w.\-/]+\.(?:py|js|out|json|md|png|mp3|mp4|html))`", RAW) if not f.startswith("..")]; check("files named in the README exist", all(os.path.exists(f) for f in named) and len(named) > 20, [f for f in named if not os.path.exists(f)])
